insert into public.topics (slug, category, title, data) values ('system-design', 'engineering', 'System design', '{"slug":"system-design","title":"System design","category":"engineering","aliases":["architecture","scalability","load balancing","caching","sharding","microservices","CAP theorem","distributed systems","HLD"],"tagline":"How you put components together so a system stays fast, reliable and affordable as it grows.","level":"intermediate","minutes":6,"concepts":["caching-strategies","sql-indexes","rest-idempotency"],"related":["postgresql","cloud-computing","rest-apis","kubernetes"],"popular":true,"what":"System design is the practice of deciding how the parts of a software system fit together: clients, APIs, databases, caches, queues and services. It''s about meeting requirements like scale, latency, reliability and cost, and being able to explain the trade-offs you made.","why":"A system that works for 100 users can fall over at 100,000. The database gets overloaded, one slow service blocks the rest, or a single server failing takes everything down. Design decisions made early, like where state lives and what can be cached, decide how painful growth will be.","how":"Most designs combine a few building blocks:\n- **Load balancer:** spreads traffic across stateless app servers.\n- **Database:** usually the hardest part to scale; add indexes, read replicas, then partitioning (sharding).\n- **Cache** (like Redis or a CDN): serves frequent reads without hitting the database.\n- **Message queue** (like Kafka, SQS or RabbitMQ): decouples slow work, such as emails or video processing, from requests.\n- **Object storage** (like S3): stores files and images.\nYou start from requirements, estimate load, sketch the simple version, and then fix the bottlenecks.","where":["Every product past the prototype stage","System design interviews for mid and senior engineering roles","Architecture reviews before building a new feature or service"],"know":["**Start from requirements:** functional (what it does) and non-functional (scale, latency, availability).","**Scale horizontally** by keeping app servers stateless.","**Caching** is the biggest cheap win, and invalidation is the hard part.","**Asynchronous processing** with queues keeps requests fast.","**Every choice is a trade-off:** consistency vs availability, cost vs latency, simplicity vs flexibility."],"analogy":"System design is like planning a restaurant kitchen. One chef works for a café. For a thousand covers a night you need stations, prep done ahead (caching), tickets passed along a rail (queues), and backup staff if someone calls in sick (redundancy).","talk10":"System design is deciding how the pieces of a system, like servers, databases, caches and queues, fit together so it stays fast and reliable as it grows, and being clear about the trade-offs.","talk30":"System design is about the architecture of a system rather than individual lines of code. You start with requirements, like how many users and how fast it must be, then combine building blocks: load balancers in front of stateless servers, a database with indexes and replicas, a cache for hot data, queues for slow background work, and object storage for files. Every choice is a trade-off, for example caching makes reads faster but data can be stale. Good system design is less about knowing every tool and more about explaining why you picked each one.","comebacks":[{"q":"Monolith or microservices?","a":"Start with a well-structured monolith in most cases. Split into services when team size or scaling needs clearly justify the extra complexity."},{"q":"What''s the CAP theorem?","a":"In a network partition, a distributed system must choose between consistency and availability. Without partitions, you can have both."},{"q":"How do you scale a database?","a":"Indexes and query tuning first, then caching, read replicas, and finally partitioning or sharding."}],"facts":["Many well-known systems started as monoliths, including Shopify, which still runs a large modular monolith.","\"There are only two hard things in computer science: cache invalidation and naming things\" is attributed to Phil Karlton."],"deeper":"### A repeatable interview structure\n1. **Clarify requirements** and what''s out of scope.\n2. **Estimate** users, requests per second, storage.\n3. **API and data model.**\n4. **High-level design:** draw the boxes.\n5. **Deep dive** into the bottleneck (often the database or a hot path).\n6. **Trade-offs and failure modes:** what breaks, and what you''d do.\n\n### Example: URL shortener\n- Write: `POST /links` generates a short code, stored with the long URL.\n- Read: `GET /:code` returns a redirect. Reads vastly outnumber writes, so cache hot codes and put a CDN in front.\n- Codes: base62 from an ID or random with collision checks.\n\n### Consistency choices\n- **Strong consistency:** reads always see the latest write; needed for balances and inventory.\n- **Eventual consistency:** replicas catch up shortly; fine for likes, views and feeds.","sources":[{"title":"Martin Kleppmann, Designing Data-Intensive Applications","url":"https://dataintensive.net/"},{"title":"AWS Well-Architected Framework","url":"https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"},{"title":"Martin Fowler: Monolith first","url":"https://martinfowler.com/bliki/MonolithFirst.html"}],"check":{"prompt":"Your product page is slow because every view runs the same expensive database query, and the data changes a few times a day. What''s the most effective first step?","options":["Shard the database","Cache the result with a sensible expiry or invalidate it on change","Rewrite the service in a faster language","Move to microservices"],"answer":1,"explanation":"Read-heavy data that changes rarely is the ideal case for caching. Sharding and rewrites are far more expensive and don''t address the repeated work."},"interview":[{"id":"system-design-iq1","q":"How would you approach a system design interview question?","level":"beginner","pro":false,"answer":"1. Clarify functional and non-functional requirements.\n2. Estimate scale: users, requests per second, data size.\n3. Define the API and data model.\n4. Draw a simple high-level design.\n5. Deep dive into bottlenecks, then discuss trade-offs and failures.","short":"I start by clarifying requirements and scale, sketch the API and data model, draw the simplest design that works, and then go deep on the bottleneck. Throughout, I explain the trade-offs rather than just naming technologies.","detail":"Interviewers mostly assess your reasoning. Saying \"I''d start simple and here''s what breaks first at 10x\" is much stronger than starting with Kafka and Kubernetes.","followups":[{"q":"How do you estimate scale?","a":"Rough numbers: daily active users times actions per user, divided by seconds in a day, and multiplied for peak traffic."}],"mistakes":["Jumping into components before clarifying requirements","Over-engineering from the start"]},{"id":"system-design-iq2","q":"How would you scale a read-heavy application?","level":"intermediate","pro":false,"answer":"1. Indexes and query optimisation.\n2. Caching: application cache (Redis) and a CDN for static and public content.\n3. Read replicas for the database.\n4. Stateless app servers behind a load balancer, scaled horizontally.\n5. Handle staleness: TTLs, invalidation, and reading from the primary where freshness matters.","short":"First I''d make sure queries are indexed. Then I''d add caching, Redis for hot data and a CDN for anything public, and add read replicas for the database. App servers stay stateless so I can add more behind a load balancer. The main trade-off is stale data, so I''d decide where freshness really matters.","detail":"Mention replication lag: a user who just updated their profile might read old data from a replica. A common fix is to read your own writes from the primary.","followups":[{"q":"What is cache stampede?","a":"Many requests miss the cache at the same moment and all hit the database. Fixes include request coalescing and staggered expiry."}],"mistakes":["Jumping straight to sharding"]},{"id":"system-design-iq3","q":"Design a notification system for email, SMS and push.","level":"advanced","pro":true,"answer":"1. API accepts notification requests and returns quickly.\n2. Requests go onto a queue; workers per channel send them through providers.\n3. Store user preferences and templates; respect opt-outs and quiet hours.\n4. Retries with backoff, idempotency to avoid duplicates, and a dead-letter queue.\n5. Track delivery status and rate-limit per user and provider.","short":"I''d have an API that validates the request and puts it on a queue, with separate workers per channel calling providers like an email service or SMS gateway. Preferences and templates are stored centrally. Workers retry with backoff, use idempotency keys so retries don''t send twice, and failures go to a dead-letter queue for inspection.","detail":"Key points: decoupling with queues so a slow SMS provider doesn''t block email; per-channel scaling; and making the \"send\" step idempotent, since retries are guaranteed to happen.","followups":[{"q":"How do you avoid sending duplicates?","a":"Give each notification an ID and record sends; workers check before sending, and providers that support idempotency keys get them."}],"mistakes":["Sending synchronously inside the user''s request"]}]}'::jsonb)
  on conflict (slug) do update set category = excluded.category, title = excluded.title, data = excluded.data, updated_at = now();
insert into public.topics (slug, category, title, data) values ('typescript', 'development', 'TypeScript', '{"slug":"typescript","title":"TypeScript","category":"development","aliases":["TS","types","static typing","tsc"],"tagline":"JavaScript with static types, checked before your code runs and erased when it ships.","level":"beginner","minutes":4,"concepts":["typescript-structural-typing"],"related":["javascript","react"],"popular":true,"what":"TypeScript is a superset of JavaScript, made by Microsoft in 2012, that adds static types. You write `.ts` files with type annotations, the TypeScript compiler checks them, and then the types are removed to produce plain JavaScript. Browsers and Node never see the types.","why":"JavaScript lets you pass anything anywhere. In a 200-line script that''s fine. In a codebase with 50 developers it means renaming a field breaks something three folders away and nobody finds out until production. TypeScript catches that class of mistake in the editor.","how":"You describe the shape of your data with types and interfaces. The compiler checks every use against those shapes. A lot of it is **inferred**, so you don''t annotate everything. TypeScript''s typing is **structural**: if an object has the right properties, it fits the type, regardless of what it''s called.","where":["Most new front-end projects (React, Angular, Vue, Svelte)","Node.js back ends and serverless functions","Library type definitions, which power editor autocomplete even for JavaScript users","Large codebases at companies like Microsoft, Google, Airbnb and Slack"],"know":["**Types exist only at compile time.** At runtime it''s just JavaScript, so it doesn''t validate API responses for you.","**Structural typing:** shape matters, not names.","**`any` turns checking off.** `unknown` is the safe alternative; you have to narrow it before use.","**Union types and narrowing** (`string | null`, then `if (x)`) handle most real-world cases.","**Generics** let you write reusable functions that keep type information, like `Array<T>`."],"analogy":"TypeScript is a spell-checker for your code''s data. It underlines the mistake while you type, and it isn''t part of the printed document.","talk10":"TypeScript is JavaScript with types. It catches mistakes like wrong property names or missing null checks while you''re writing code, and then it compiles down to normal JavaScript.","talk30":"TypeScript adds a static type system on top of JavaScript. You describe what your data looks like, the compiler checks every use, and your editor gets much better autocomplete and refactoring. The types are erased at build time, so there''s no runtime cost, but that also means it can''t validate data coming from outside, like API responses. You still need runtime validation for that, often with a library like Zod. Its typing is structural, so anything with the right shape fits.","comebacks":[{"q":"Doesn''t it slow you down?","a":"A little at the start. On a team or a big codebase, it usually saves more time than it costs, mainly on refactors."},{"q":"Does TypeScript make code faster?","a":"No. Types are removed, so runtime performance is the same as JavaScript."},{"q":"Is it a different language?","a":"It''s JavaScript plus types. Valid JavaScript is very close to valid TypeScript."}],"facts":["Anders Hejlsberg, who led TypeScript, also designed C# and Turbo Pascal.","TypeScript''s type system is Turing-complete, which is why people build games out of types for fun.","Node.js can now run TypeScript files directly by stripping the types."],"deeper":"### Structural typing in practice\n```ts\ninterface Point { x: number; y: number }\nconst p = { x: 1, y: 2, label: ''a'' }\nconst q: Point = p // OK: it has x and y\n```\nAssigning an object literal directly with an extra property is flagged (\"excess property check\"), but a variable is not. That catches typos without breaking structural typing.\n\n### Narrowing\n```ts\nfunction len(x: string | string[]) {\n  return typeof x === ''string'' ? x.length : x.join('''').length\n}\n```\nThe compiler follows your `if`, `typeof`, `in` and discriminant checks to know the type in each branch.\n\n### Trade-offs\n- Complex generic types can become hard to read. Prefer simple types that people can maintain.\n- Types can lie if data comes from outside. Validate at the boundaries.","sources":[{"title":"TypeScript handbook","url":"https://www.typescriptlang.org/docs/handbook/intro.html"},{"title":"TypeScript handbook: Type compatibility","url":"https://www.typescriptlang.org/docs/handbook/type-compatibility.html"}],"check":{"prompt":"Your API returns JSON, and you type it as `User` with `as User`. The server sends a field as `null` when the type says `string`. What happens?","options":["TypeScript throws a runtime error","The build fails","Nothing at first; you get a runtime bug when code uses it as a string","TypeScript converts null to an empty string"],"answer":2,"explanation":"Types are erased at runtime, and `as` tells the compiler to trust you. Nothing checks the real data. Validate external data at runtime if it matters."},"interview":[{"id":"typescript-iq1","q":"What is TypeScript and why use it over JavaScript?","level":"beginner","pro":false,"answer":"1. A typed superset of JavaScript that compiles to JavaScript.\n2. Catches type errors at compile time, before the code runs.\n3. Better editor support: autocomplete, safe refactoring, inline docs.\n4. Types are erased, so there''s no runtime cost and no runtime checking.","short":"TypeScript is JavaScript with static types. It catches a whole class of bugs in the editor and makes refactoring safer, and it compiles away to plain JavaScript, so there''s no runtime cost.","detail":"Strong answers mention the trade-off: it''s a compile-time tool. Data from APIs, forms or local storage still needs runtime validation. Mentioning `strict` mode and avoiding `any` shows you''ve used it seriously.","followups":[{"q":"What''s the difference between `any` and `unknown`?","a":"Both accept anything. `any` turns off checking; `unknown` forces you to narrow the type before using it."},{"q":"Interface vs type alias?","a":"They overlap a lot. Interfaces can be extended and merged; type aliases can express unions and mapped types. Pick one convention per codebase."}],"mistakes":["Claiming TypeScript validates data at runtime"]},{"id":"typescript-iq2","q":"What is structural typing?","level":"intermediate","pro":false,"answer":"1. Types are compatible if their shapes match, regardless of their names.\n2. Opposite of nominal typing (Java, C#), where the declared type name matters.\n3. Makes JavaScript patterns like plain objects work naturally.","short":"In TypeScript, if something has the properties a type needs, it fits that type. The name doesn''t matter, only the shape. Java is the opposite: it checks declared names.","detail":"Mention the practical consequence: two different types with the same shape are interchangeable, which can hide mistakes, like passing a `UserId` where an `OrderId` is expected if both are just strings. \"Branded types\" are the common workaround.","followups":[{"q":"How do you get nominal-style safety?","a":"Branded types: add a fake unique property like `string & { __brand: ''UserId'' }`."}],"mistakes":["Confusing structural typing with dynamic typing"]},{"id":"typescript-iq3","q":"Explain generics with an example.","level":"intermediate","pro":true,"answer":"1. Generics let a function or type work with many types while keeping the type information.\n2. Example: `function first<T>(xs: T[]): T | undefined`.\n3. Constraints (`T extends { id: string }`) restrict what T can be.","short":"Generics are type parameters. A function like `first<T>` takes an array of T and returns a T, so if you pass numbers you get a number back, not `any`.","detail":"Real examples help: `useState<T>`, `Promise<T>`, `Array<T>`, or an API helper `get<T>(url): Promise<T>`. Mention that generics should be inferred from arguments most of the time rather than passed explicitly.","followups":[{"q":"What does `keyof` do?","a":"It gives a union of an object type''s property names, used with generics to type-safe property access."}],"mistakes":["Using generics where a plain union type would be simpler"]}]}'::jsonb)
  on conflict (slug) do update set category = excluded.category, title = excluded.title, data = excluded.data, updated_at = now();
insert into public.topics (slug, category, title, data) values ('vector-databases', 'ai', 'Vector databases', '{"slug":"vector-databases","title":"Vector databases","category":"ai","aliases":["vector DB","embeddings","pgvector","Pinecone","Weaviate","Qdrant","similarity search","semantic search","ANN"],"tagline":"Databases that find things by meaning, by storing embeddings and searching for the nearest ones.","level":"intermediate","minutes":4,"concepts":["embeddings-vector-db","rag"],"related":["rag","llms","postgresql"],"popular":false,"what":"A vector database stores **embeddings**, which are lists of numbers that represent the meaning of text, images or other data. It''s built to answer one question fast: \"which stored items are closest to this one?\" That lets you search by meaning instead of exact words.","why":"Keyword search fails when people use different words for the same thing. \"Laptop won''t turn on\" and \"notebook doesn''t power up\" share no keywords. Embedding models place them close together in vector space, and a vector database finds them, even across millions of items, in milliseconds.","how":"An embedding model turns each item into a vector with hundreds or thousands of dimensions. The database indexes those vectors, typically with an **approximate nearest neighbour** (ANN) index such as HNSW. At query time you embed the query and the index returns the most similar vectors, measured by cosine similarity or a similar distance. \"Approximate\" means it trades a tiny bit of accuracy for huge speed gains.","where":["Retrieval for RAG systems","Semantic search on websites and documentation","Recommendations (\"products similar to this one\")","Duplicate detection for support tickets, images or questions"],"know":["**Embeddings come from a model.** Changing the embedding model means re-embedding everything.","**Approximate search** is the norm. It''s very fast and nearly always right.","**Metadata filters** (date, owner, permissions) are as important as similarity.","**You may not need a new database:** Postgres with pgvector handles many workloads.","**Hybrid search** combining vectors and keywords usually performs best."],"analogy":"Imagine a library where books are shelved by what they''re about instead of alphabetically. A book on \"fixing slow websites\" sits next to \"web performance tuning\". A vector database is that library, plus a librarian who can walk straight to the right shelf.","talk10":"A vector database stores embeddings, numeric representations of meaning, and finds the most similar ones quickly. It''s what lets you search by meaning instead of exact keywords.","talk30":"A vector database is built around embeddings. You run your text, or images, through an embedding model that turns each item into a long list of numbers, where similar meanings end up close together. The database indexes those vectors so it can find the nearest ones to a query in milliseconds, using approximate nearest-neighbour algorithms like HNSW. It''s the retrieval layer behind most RAG systems and semantic search. You don''t always need a dedicated product; Postgres with the pgvector extension covers a lot of use cases.","comebacks":[{"q":"Is it a replacement for a normal database?","a":"Usually not. It''s for similarity search. Your users, orders and transactions still belong in a regular database."},{"q":"Why approximate?","a":"Exact search compares the query with every vector, which is too slow at scale. Approximate indexes are dramatically faster and almost as accurate."}],"facts":["HNSW stands for Hierarchical Navigable Small World, a graph-based index described in 2016.","Common embedding sizes range from a few hundred to a few thousand dimensions."],"deeper":"### Similarity measures\n- **Cosine similarity:** compares the angle between vectors, ignoring length. The most common for text.\n- **Dot product:** fast, and equal to cosine when vectors are normalised.\n- **Euclidean distance:** straight-line distance.\n\n### pgvector example\n```sql\ncreate extension if not exists vector;\ncreate table docs (id bigserial primary key, body text, embedding vector(1536));\ncreate index on docs using hnsw (embedding vector_cosine_ops);\nselect id, body from docs order by embedding <=> $1 limit 5;\n```\n`<=>` is cosine distance. Keeping vectors next to your relational data makes permission filters and joins easy.\n\n### Trade-offs\n- Dedicated vector databases can scale further and add features; Postgres keeps your stack simpler.\n- HNSW indexes use a lot of memory and take time to build.","sources":[{"title":"pgvector documentation","url":"https://github.com/pgvector/pgvector"},{"title":"Malkov and Yashunin, HNSW paper","url":"https://arxiv.org/abs/1603.09320"}],"check":{"prompt":"You switch to a new, better embedding model. What do you have to do with your existing vectors?","options":["Nothing, vectors from different models are compatible","Re-embed all stored items with the new model","Only re-embed new documents","Normalise the old vectors"],"answer":1,"explanation":"Each model has its own vector space. Comparing a query from model B against documents embedded by model A gives meaningless results."},"interview":[{"id":"vector-databases-iq1","q":"What is a vector database and when would you use one?","level":"beginner","pro":false,"answer":"1. Stores embeddings and searches for the most similar vectors.\n2. Enables semantic search: matching by meaning, not exact words.\n3. Uses approximate nearest-neighbour indexes for speed.\n4. Use cases: RAG, semantic search, recommendations, deduplication.","short":"A vector database stores embeddings and finds the closest ones to a query, so you can search by meaning. I''d use one for semantic search or as the retrieval layer in a RAG system. For smaller projects, pgvector in Postgres is often enough.","detail":"Mention that it complements rather than replaces a relational database, and that metadata filtering, like permissions, is essential in real products.","followups":[{"q":"What is cosine similarity?","a":"A measure of how closely two vectors point in the same direction, from -1 to 1. Higher means more similar."}],"mistakes":["Suggesting a vector database to store all application data"]},{"id":"vector-databases-iq2","q":"Dedicated vector DB or pgvector?","level":"intermediate","pro":true,"answer":"1. pgvector: one database, transactions, joins and permission filters next to your data; simpler operations.\n2. Dedicated vector DB: better at very large scale, more specialised features, separate scaling.\n3. Decide by data size, query volume, filtering needs and team operations.","short":"If I already use Postgres and have up to a few million vectors, I''d start with pgvector, since it keeps permissions and joins simple. I''d move to a dedicated vector database if scale or latency requirements outgrow it.","detail":"Interviewers like hearing that you''d measure first: latency at your expected data size, and recall at your index settings.","followups":[{"q":"What is recall in vector search?","a":"The fraction of the true nearest neighbours the approximate index actually returns."}],"mistakes":["Choosing a dedicated vector database by default for a small prototype"]}]}'::jsonb)
  on conflict (slug) do update set category = excluded.category, title = excluded.title, data = excluded.data, updated_at = now();
insert into public.questions (id, topic, difficulty, pro, data) values ('q-url-dns', 'fundamentals', 'beginner', false, '{"id":"q-url-dns","topic":"fundamentals","difficulty":"beginner","pro":false,"prompt":"You type `techyapper.sumitsk.in` and press Enter. Before any HTTP request can be sent, what must happen first?","options":["The browser downloads the site''s JavaScript","The hostname is resolved to an IP address via DNS","The server sends a TLS certificate","The browser checks the service worker for HTML"],"answer":1,"explanation":"Networking runs on IP addresses, not names. The browser checks its own cache, then the OS, then asks a DNS resolver to turn the hostname into an IP. Only then can it open a TCP (or QUIC) connection, negotiate TLS, and send the HTTP request.\n\nA service worker can intercept requests for a site you''ve *already* visited — but on a first visit there''s nothing installed yet."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-http-status', 'backend', 'beginner', false, '{"id":"q-http-status","topic":"backend","difficulty":"beginner","pro":false,"prompt":"An API returns `401 Unauthorized`. What is it actually telling you?","options":["You haven''t proven who you are — credentials are missing or invalid","You''re logged in but not allowed to do this","The resource doesn''t exist","The server crashed"],"answer":0,"explanation":"Despite the name, 401 is about **authentication**: \"I don''t know who you are.\" Send valid credentials and retry. **403 Forbidden** is the authorisation one: \"I know who you are, and the answer is still no.\" Mixing them up is one of the most common API-design slips."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-git-commit', 'fundamentals', 'beginner', false, '{"id":"q-git-commit","topic":"fundamentals","difficulty":"beginner","pro":false,"prompt":"What does `git commit` store?","options":["Only the lines you changed (a diff)","A snapshot of the staged project tree, plus a pointer to its parent commit","A copy of the whole working directory, including untracked files","A message that is sent to the remote"],"answer":1,"explanation":"Git stores **snapshots**, not diffs. A commit points to a tree object (the full directory state at that moment, de-duplicated by content hash) and to its parent commit(s). Diffs are computed on demand when you run `git diff` or `git log -p`. Nothing goes to a remote until you push."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-sql-where-having', 'databases', 'beginner', false, '{"id":"q-sql-where-having","topic":"databases","difficulty":"beginner","pro":false,"prompt":"What''s the difference between `WHERE` and `HAVING`?","options":["`WHERE` filters rows before grouping; `HAVING` filters groups after aggregation","They''re interchangeable; `HAVING` is just older syntax","`HAVING` is faster because it uses indexes","`WHERE` only works on numbers"],"answer":0,"explanation":"SQL evaluates `FROM` → `WHERE` → `GROUP BY` → `HAVING` → `SELECT` → `ORDER BY`. So `WHERE` can''t see `COUNT(*)` — the groups don''t exist yet. `HAVING COUNT(*) > 5` filters after aggregation. Filter as early as possible with `WHERE`: fewer rows reach the expensive grouping step."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-docker-image-container', 'devops', 'beginner', false, '{"id":"q-docker-image-container","topic":"devops","difficulty":"beginner","pro":false,"prompt":"Image vs container — which statement is right?","options":["An image is a running process; a container is the file on disk","An image is a read-only template; a container is a running instance of it with its own writable layer","They''re the same thing with different names","Containers are virtual machines built from images"],"answer":1,"explanation":"Think class and object. The image is an immutable stack of filesystem layers plus config. `docker run` creates a container: a thin writable layer on top of the image and an isolated process. Delete the container and its writable layer goes with it — which is why data belongs in volumes."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-js-const', 'languages', 'beginner', false, '{"id":"q-js-const","topic":"languages","difficulty":"beginner","pro":false,"prompt":"What happens?","code":{"lang":"js","source":"const user = { name: ''Asha'' }\nuser.name = ''Ravi''"},"options":["TypeError: Assignment to constant variable","It works — `user.name` is now ''Ravi''","It silently does nothing","SyntaxError"],"answer":1,"explanation":"`const` makes the **binding** constant: you can''t point `user` at a different object. The object itself is still mutable. If you want an immutable object, use `Object.freeze` (shallow) — or better, don''t mutate and create new objects instead."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-rest-put-patch', 'backend', 'beginner', false, '{"id":"q-rest-put-patch","topic":"backend","difficulty":"beginner","pro":false,"prompt":"What''s the conventional difference between `PUT` and `PATCH`?","options":["`PUT` replaces the whole resource; `PATCH` applies a partial update","`PUT` creates; `PATCH` deletes","`PATCH` is idempotent; `PUT` isn''t","There''s no difference"],"answer":0,"explanation":"`PUT /users/7` with a body means \"make the resource look exactly like this\". `PATCH` sends only the changes. `PUT` is defined as idempotent — sending it twice leaves the same state. `PATCH` *can* be idempotent, but isn''t guaranteed to be (think \"increment counter\")."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-llm-hallucinate', 'ai', 'beginner', false, '{"id":"q-llm-hallucinate","topic":"ai","difficulty":"beginner","pro":false,"prompt":"Why do LLMs sometimes state false things confidently?","options":["They''re programmed to guess when they don''t have internet access","They generate the most plausible next tokens, and plausible isn''t the same as true","Their database of facts has errors","Hallucination only happens when the temperature is set to 0"],"answer":1,"explanation":"An LLM has no lookup table of facts. It predicts likely continuations based on patterns learned in training. When the pattern of a correct-sounding answer is strong but the specific fact is weak or missing, you get fluent fiction. Grounding (RAG), citations and tool use reduce this; low temperature doesn''t remove it."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-power-apps-delegation', 'lowcode', 'beginner', false, '{"id":"q-power-apps-delegation","topic":"lowcode","difficulty":"beginner","pro":false,"prompt":"A Power Apps gallery uses `Filter(Orders, Status = \"Open\")` on a 50,000-row SharePoint list and shows a blue delegation warning. What''s the risk?","options":["The app will crash on launch","The filter may run locally on only the first 500–2,000 rows, silently missing matches","SharePoint will lock the list","Nothing — the warning is cosmetic"],"answer":1,"explanation":"When an expression can''t be delegated to the data source, Power Apps downloads only the first N rows (500 by default, configurable up to 2,000) and filters them on the device. No error — just quietly incomplete results. Use delegable functions and columns for your data source, or move the logic server-side."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-css-box', 'frontend', 'beginner', false, '{"id":"q-css-box","topic":"frontend","difficulty":"beginner","pro":false,"prompt":"With `box-sizing: border-box`, an element has `width: 200px; padding: 20px; border: 2px solid`. How wide is it on screen?","options":["200px","244px","240px","222px"],"answer":0,"explanation":"`border-box` makes `width` include padding and border, so the content area shrinks to 156px and the element stays 200px. With the default `content-box`, it''d be 200 + 40 + 4 = 244px. That''s why nearly every CSS reset sets `border-box` globally."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-hash-vs-encrypt', 'security', 'beginner', false, '{"id":"q-hash-vs-encrypt","topic":"security","difficulty":"beginner","pro":false,"prompt":"Why should passwords be hashed rather than encrypted?","options":["Hashing is faster to reverse when users forget their password","Hashes are one-way, so a database leak doesn''t hand attackers a decryption key to every password","Encryption isn''t allowed by law","Hashes take less storage"],"answer":1,"explanation":"Encryption is reversible by design — whoever holds the key can recover every password. A password hash (bcrypt, scrypt, Argon2) is one-way and deliberately slow, with a unique salt per user. You verify by hashing the login attempt and comparing. That''s why \"forgot password\" sends a reset link, never your old password."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-python-list-tuple', 'languages', 'beginner', false, '{"id":"q-python-list-tuple","topic":"languages","difficulty":"beginner","pro":false,"prompt":"Which is a real reason to use a tuple instead of a list in Python?","options":["Tuples can hold more items","Tuples are immutable, so they can be dictionary keys or set members (if their items are hashable)","Tuples are always sorted","Lists can''t hold mixed types"],"answer":1,"explanation":"Immutability makes tuples hashable, so `{(lat, lng): \"Pune\"}` works while a list key raises `TypeError`. They also signal intent — \"this is a fixed record\" — and are slightly cheaper to create."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-useeffect-deps', 'frontend', 'intermediate', false, '{"id":"q-useeffect-deps","topic":"frontend","difficulty":"intermediate","pro":false,"prompt":"`filters` is created inline as `{ q, page }` during render. What happens?","code":{"lang":"jsx","source":"useEffect(() => {\n  fetchResults(filters)\n}, [filters])"},"options":["The effect runs once, on mount","The effect runs only when `q` or `page` change","The effect runs after every render, because a new object is created each time","React throws a dependency warning and skips the effect"],"answer":2,"explanation":"Dependencies are compared with `Object.is`. A fresh object literal is a new reference on every render, so the effect re-runs every time — often an infinite fetch loop if the fetch sets state. Depend on the primitives (`[q, page]`) or memoise the object with `useMemo`."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-event-loop-order', 'languages', 'intermediate', false, '{"id":"q-event-loop-order","topic":"languages","difficulty":"intermediate","pro":false,"prompt":"In what order are these logged?","code":{"lang":"js","source":"console.log(''A'')\nsetTimeout(() => console.log(''B''), 0)\nPromise.resolve().then(() => console.log(''C''))\nconsole.log(''D'')"},"options":["A B C D","A D B C","A D C B","A C D B"],"answer":2,"explanation":"Synchronous code runs first: A, D. Then the engine drains the **microtask queue** (promise callbacks): C. Only then does the event loop take the next **macrotask** (the timer): B. `setTimeout(fn, 0)` means \"no sooner than the next macrotask\", not \"immediately\"."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-index-like', 'databases', 'intermediate', false, '{"id":"q-index-like","topic":"databases","difficulty":"intermediate","pro":false,"prompt":"There''s a B-tree index on `users(email)`. Which query can''t use it to seek efficiently?","options":["`WHERE email = ''a@b.com''`","`WHERE email LIKE ''asha%''`","`WHERE email LIKE ''%@gmail.com''`","`WHERE email > ''m''`"],"answer":2,"explanation":"A B-tree is sorted left to right, like a phone book. A known prefix lets the database jump to the right place. A leading wildcard means \"could start with anything\", so it falls back to scanning. For suffix or substring search, look at trigram indexes (`pg_trgm`) or full-text search. (In Postgres, prefix `LIKE` also needs a C collation or a `text_pattern_ops` index.)"}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-jwt-logout', 'security', 'intermediate', false, '{"id":"q-jwt-logout","topic":"security","difficulty":"intermediate","pro":false,"prompt":"Your API uses stateless JWT access tokens valid for 24 hours. A user clicks \"log out everywhere\". What''s the honest problem?","options":["JWTs can''t be deleted from the browser","Already-issued tokens stay valid until they expire unless you add server-side state (a denylist or token version)","The signature becomes invalid and the user gets a 500 error","JWTs are encrypted, so the server can''t read the expiry"],"answer":1,"explanation":"A JWT is valid if its signature checks out and it hasn''t expired — no database lookup. That''s the scalability win and the revocation weakness. Real systems use short-lived access tokens (minutes) plus revocable refresh tokens, or check a per-user token version. Also: standard JWTs are *signed*, not encrypted — anyone can read the payload."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-rag-why', 'genai', 'intermediate', false, '{"id":"q-rag-why","topic":"genai","difficulty":"intermediate","pro":false,"prompt":"What problem does Retrieval-Augmented Generation mainly solve?","options":["It makes the model smaller and faster","It grounds answers in your own, current documents without retraining the model","It replaces the need for prompts","It permanently teaches the model new facts"],"answer":1,"explanation":"RAG retrieves relevant chunks (usually by embedding similarity, often combined with keyword search) and puts them in the prompt. The model''s weights don''t change. You get answers about private or fresh data, with citations, and updating knowledge is just re-indexing documents. Quality depends heavily on chunking and retrieval — garbage retrieved, garbage generated."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-docker-layer-cache', 'devops', 'intermediate', false, '{"id":"q-docker-layer-cache","topic":"devops","difficulty":"intermediate","pro":false,"prompt":"Why do Node Dockerfiles usually `COPY package*.json` and `RUN npm ci` *before* `COPY . .`?","options":["npm requires package.json to be copied first","So the dependency layer is cached and only rebuilt when the manifests change, not on every code edit","It reduces the image''s attack surface","Docker copies files in alphabetical order anyway"],"answer":1,"explanation":"Each instruction creates a layer, and a layer is reused if its inputs haven''t changed. Copy your whole source first and any edit invalidates the cache, forcing a full reinstall. Copy manifests first and day-to-day builds skip straight past `npm ci`. Order instructions from least to most frequently changing."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-mvcc-reads', 'databases', 'intermediate', false, '{"id":"q-mvcc-reads","topic":"databases","difficulty":"intermediate","pro":false,"prompt":"In PostgreSQL, a long report query is reading `orders` while other transactions update rows. Why don''t readers and writers block each other?","options":["Postgres locks the whole table for readers","MVCC: writers create new row versions, and each transaction reads from its own snapshot","Reads go to a replica automatically","Updates are queued until all reads finish"],"answer":1,"explanation":"Postgres never overwrites a row in place. An `UPDATE` writes a new tuple version and marks the old one as expired by that transaction. Each query sees the versions visible to its snapshot. The cost: dead tuples pile up and must be cleaned by `VACUUM` — and very long transactions stop that cleanup."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-cors-who', 'security', 'intermediate', false, '{"id":"q-cors-who","topic":"security","difficulty":"intermediate","pro":false,"prompt":"Who enforces CORS?","options":["The API server blocks cross-origin requests","The browser — it withholds the response from page JavaScript unless the server''s headers allow that origin","The DNS provider","The firewall"],"answer":1,"explanation":"CORS is a browser rule that *relaxes* the same-origin policy. The server only sends headers like `Access-Control-Allow-Origin`; the browser decides whether your JS may read the response. That''s why `curl` or Postman \"works\" when your frontend doesn''t — they aren''t browsers. CORS is not an authentication mechanism."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-ts-any-unknown', 'languages', 'intermediate', false, '{"id":"q-ts-any-unknown","topic":"languages","difficulty":"intermediate","pro":false,"prompt":"What''s the practical difference between `any` and `unknown` in TypeScript?","options":["`unknown` is just an alias for `any`","You can do anything with `any`; with `unknown` you must narrow the type before using it","`unknown` can only hold `null` or `undefined`","`any` is checked at runtime, `unknown` isn''t"],"answer":1,"explanation":"`any` switches the type checker off — and it spreads. `unknown` says \"this could be anything, so prove it\": you need a `typeof` check, a type guard or validation (e.g. zod) before calling methods on it. Use `unknown` for JSON, `catch` errors and untrusted input."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-cache-invalidation', 'system-design', 'intermediate', false, '{"id":"q-cache-invalidation","topic":"system-design","difficulty":"intermediate","pro":false,"prompt":"You cache product pages for 10 minutes. A price changes. What''s the most common fix that keeps the cache *and* correct prices?","options":["Disable caching for product pages","Lower the TTL to 1 second","Invalidate (or update) the cache entry when the price is written, keeping the TTL as a safety net","Ask users to hard-refresh"],"answer":2,"explanation":"Pure TTL caching trades freshness for simplicity. Event-driven invalidation — delete or rewrite the key whenever the source of truth changes — gives you fresh data with high hit rates. Keep a TTL anyway so a missed invalidation heals itself."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-node-cpu', 'backend', 'intermediate', false, '{"id":"q-node-cpu","topic":"backend","difficulty":"intermediate","pro":false,"prompt":"A Node.js API calculates a large PDF report synchronously inside a request handler. What happens to other users'' requests during that time?","options":["They''re handled in parallel by other threads automatically","They wait — the event loop is blocked until the synchronous work finishes","Node kills the slow request after 100ms","They''re routed to a different CPU core"],"answer":1,"explanation":"Your JavaScript runs on one thread. I/O is offloaded, but CPU-heavy synchronous code holds the event loop hostage. Move it to a worker thread, a job queue or a separate service — or run multiple processes (cluster/PM2/containers) so one blocked loop isn''t fatal."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-embeddings-what', 'ai', 'intermediate', false, '{"id":"q-embeddings-what","topic":"ai","difficulty":"intermediate","pro":false,"prompt":"In a vector database, what does \"these two embeddings have high cosine similarity\" mean?","options":["The two texts share many identical words","Their vectors point in a similar direction, which the model learned to correlate with similar meaning","They were created at the same time","They''re stored on the same disk page"],"answer":1,"explanation":"An embedding model maps text to a point in a high-dimensional space where semantic similarity becomes geometric closeness. \"Reset my password\" and \"I can''t log in\" can be close with zero shared words. Cosine similarity compares direction, ignoring length."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-supabase-rls-anon', 'backend', 'intermediate', false, '{"id":"q-supabase-rls-anon","topic":"backend","difficulty":"intermediate","pro":false,"prompt":"A Supabase app ships its anon key in the browser bundle. What actually stops a user from reading everyone''s rows?","options":["The anon key is encrypted in the bundle","Supabase hides tables from browsers by default","Row Level Security policies on each table, evaluated against the user''s JWT","The frontend only queries the user''s own rows"],"answer":2,"explanation":"The anon key is public by design — it just identifies the project. Protection comes from Postgres RLS: with RLS enabled and a policy like `using (auth.uid() = user_id)`, the database itself filters rows. Frontend filtering is a UX choice, not security. Never ship the service-role key, which bypasses RLS."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-big-o-hash', 'fundamentals', 'intermediate', false, '{"id":"q-big-o-hash","topic":"fundamentals","difficulty":"intermediate","pro":false,"prompt":"Why is average lookup in a hash map O(1) but worst case O(n)?","options":["Hash maps sort keys once they get big","If many keys collide into the same bucket, lookup degrades to scanning that bucket","The hash function becomes slower as the map grows","Worst case only happens with string keys"],"answer":1,"explanation":"A good hash spreads keys evenly, so each bucket holds ~1 item. Adversarial or pathological inputs can force collisions. That''s why languages randomise hash seeds (Python, Rust) and some implementations (Java''s HashMap) turn long buckets into balanced trees, capping worst case at O(log n)."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-react-keys', 'frontend', 'advanced', false, '{"id":"q-react-keys","topic":"frontend","difficulty":"advanced","pro":false,"prompt":"A list renders `items.map((item, i) => <Row key={i} {...item} />)`. Each `Row` has an uncontrolled text input. The user types into row 2, then an item is inserted at the top. What happens?","options":["Everything works — React tracks the input by its DOM position","The typed text appears in the wrong row, because state stays attached to index 2, which is now a different item","React throws a duplicate key error","All inputs are cleared"],"answer":1,"explanation":"Keys tell React which element is which across renders. With index keys, inserting at the top shifts every index: React thinks the components are the same and just updates props, so DOM state and component state stay at the old position. Use a stable id from your data."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-isolation-lost-update', 'databases', 'advanced', false, '{"id":"q-isolation-lost-update","topic":"databases","difficulty":"advanced","pro":false,"prompt":"Two requests run `SELECT balance` then `UPDATE accounts SET balance = <read value> - 100` concurrently under Postgres''s default isolation (Read Committed). Both read 500. What''s the final balance?","options":["300 — Postgres serialises them","400 — a lost update; one withdrawal overwrote the other","The second transaction fails with a serialization error","500 — both roll back"],"answer":1,"explanation":"Read Committed prevents dirty reads, not lost updates in read-modify-write patterns done in application code. Fixes: do it atomically (`SET balance = balance - 100`), lock the row (`SELECT … FOR UPDATE`), use optimistic concurrency with a version column, or run at Serializable and retry on failure."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-rag-chunking', 'genai', 'advanced', false, '{"id":"q-rag-chunking","topic":"genai","difficulty":"advanced","pro":false,"prompt":"Your RAG bot answers policy questions badly: it retrieves the right document but the wrong part of it. Which change is most likely to help first?","options":["Switch to a bigger LLM","Raise the temperature","Revisit chunking — sensible boundaries, some overlap, headings attached to chunks — and re-rank the top results","Store the whole document as one embedding"],"answer":2,"explanation":"Retrieval quality caps generation quality. Chunks that split a rule from its exception, or lose the section title, retrieve poorly. Structure-aware chunking with metadata, hybrid search (BM25 + vectors) and a cross-encoder re-ranker typically beat model upgrades for this failure mode."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-idempotency-key', 'system-design', 'advanced', false, '{"id":"q-idempotency-key","topic":"system-design","difficulty":"advanced","pro":false,"prompt":"A mobile client sends `POST /payments`, the network times out, and the client retries. How do you prevent a double charge?","options":["Use `PUT` instead of `POST`","Make the timeout longer","Have the client send an idempotency key; the server stores the first result for that key and returns it for retries","Rate-limit the endpoint to one request per minute"],"answer":2,"explanation":"The client can''t know whether the first request succeeded. With an `Idempotency-Key` header (as Stripe and Razorpay-style APIs do), the server records key → outcome atomically. A retry with the same key returns the stored response instead of charging again. Keys need a unique constraint and an expiry."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-gil-threads', 'languages', 'advanced', false, '{"id":"q-gil-threads","topic":"languages","difficulty":"advanced","pro":false,"prompt":"A CPU-bound Python (CPython) function is split across 8 threads. Why doesn''t it get ~8× faster?","options":["Python threads are not real OS threads","The GIL lets only one thread execute Python bytecode at a time in a process","Python automatically limits threads to one CPU core via the OS","The threads are blocked by the garbage collector"],"answer":1,"explanation":"CPython threads are real OS threads, but the Global Interpreter Lock serialises bytecode execution. Threads still help for I/O-bound work (the GIL is released while waiting). For CPU-bound work use `multiprocessing`, native extensions that release the GIL (NumPy), or the free-threaded builds introduced in Python 3.13."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-cors-preflight', 'security', 'advanced', false, '{"id":"q-cors-preflight","topic":"security","difficulty":"advanced","pro":false,"prompt":"Your frontend sends `fetch(api, { method: ''POST'', headers: { ''Content-Type'': ''application/json'' } })` to another origin. Before the POST, the browser sends an `OPTIONS` request. Why?","options":["To check whether the server is online","JSON content-type makes it a non-simple request, so the browser preflights to ask if the method and headers are allowed","OPTIONS is required for every HTTPS request","To download the CORS policy file"],"answer":1,"explanation":"\"Simple\" requests (GET/HEAD/POST with form-like content types and no custom headers) skip preflight. `application/json`, `Authorization` headers or `PUT/DELETE` trigger an `OPTIONS` preflight. The server must answer with matching `Access-Control-Allow-Methods/Headers`. `Access-Control-Max-Age` lets browsers cache that answer."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-k8s-liveness', 'cloud', 'advanced', false, '{"id":"q-k8s-liveness","topic":"cloud","difficulty":"advanced","pro":false,"prompt":"A service''s liveness probe calls an endpoint that checks the database. The database has a 2-minute outage. What can go wrong?","options":["Nothing — that''s what probes are for","Every pod fails liveness and gets restarted repeatedly, turning a database blip into a full outage and restart storm","The database gets restarted by Kubernetes","Kubernetes scales the deployment to zero"],"answer":1,"explanation":"Liveness should answer \"is this process wedged?\", not \"are my dependencies healthy?\". Dependency checks belong in readiness probes, which take pods out of load balancing without killing them. Coupling liveness to downstream health causes cascading restarts."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-ts-structural', 'languages', 'advanced', false, '{"id":"q-ts-structural","topic":"languages","difficulty":"advanced","pro":false,"prompt":"What does TypeScript do?","code":{"lang":"ts","source":"type UserId = string\ntype OrderId = string\nfunction cancel(id: OrderId) {}\nconst u: UserId = ''u_123''\ncancel(u)"},"options":["Error: UserId is not assignable to OrderId","Compiles fine — both aliases are just `string`, and TS is structurally typed","Runtime error","Compiles only with `strict: false`"],"answer":1,"explanation":"Type aliases don''t create new types; structurally, both are `string`. To prevent mixing IDs, use a branded type: `type OrderId = string & { readonly __brand: ''OrderId'' }` and create values through a constructor function."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-sd-queue', 'system-design', 'advanced', true, '{"id":"q-pro-sd-queue","topic":"system-design","difficulty":"advanced","pro":true,"prompt":"An order service publishes \"OrderPlaced\" to a queue after writing to its DB. Sometimes the DB write succeeds but the publish fails. Which pattern fixes this without distributed transactions?","options":["Publish first, then write to the DB","Retry the publish forever in the request handler","Transactional outbox: write the event to an outbox table in the same DB transaction, and relay it to the queue asynchronously","Use a bigger queue"],"answer":2,"explanation":"The dual-write problem: two systems, no shared transaction. The outbox makes the event part of the same atomic DB commit; a relay (polling or CDC like Debezium) publishes it, at least once. Consumers must therefore be idempotent."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-sd-consistent-hash', 'system-design', 'advanced', true, '{"id":"q-pro-sd-consistent-hash","topic":"system-design","difficulty":"advanced","pro":true,"prompt":"Why do distributed caches use consistent hashing instead of `hash(key) % N`?","options":["It''s faster to compute","When a node is added or removed, only about 1/N of keys move instead of almost all of them","It guarantees no hot keys","It encrypts keys"],"answer":1,"explanation":"With modulo, changing N remaps nearly every key — a cache stampede on every scale event. Consistent hashing places nodes and keys on a ring; a key belongs to the next node clockwise. Virtual nodes smooth the distribution."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-genai-eval', 'genai', 'intermediate', true, '{"id":"q-pro-genai-eval","topic":"genai","difficulty":"intermediate","pro":true,"prompt":"You change your RAG prompt and answers \"feel better\". What should you do before shipping?","options":["Ship it — vibes are a valid metric","Run it against a fixed evaluation set and compare retrieval and answer metrics with the old version","Ask the LLM if its answers improved","Increase max tokens"],"answer":1,"explanation":"Without an eval set you can''t tell improvement from regression on cases you didn''t look at. Keep a set of real questions with expected sources/answers; measure retrieval hit rate, faithfulness and correctness. LLM-as-judge can help scale grading, but calibrate it against human labels."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-genai-context', 'genai', 'advanced', true, '{"id":"q-pro-genai-context","topic":"genai","difficulty":"advanced","pro":true,"prompt":"A model has a 200k-token context window. Why might stuffing in 150k tokens of documents still give worse answers than a good RAG pipeline?","options":["Models ignore everything after 8k tokens","Relevant details get diluted — models attend less reliably to facts buried mid-context, and cost and latency grow with every token","Long contexts are always truncated by the API","RAG uses a different model"],"answer":1,"explanation":"Long context is great, but \"lost in the middle\" effects, distraction by near-miss passages, and per-token cost are real. Retrieving the top relevant chunks keeps prompts focused and cheap. Many systems combine both: retrieve generously, then let a long-context model reason over it."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-be-jwt-alg', 'backend', 'advanced', true, '{"id":"q-pro-be-jwt-alg","topic":"backend","difficulty":"advanced","pro":true,"prompt":"Why is accepting the `alg` value from a JWT header dangerous?","options":["It makes tokens larger","An attacker can switch algorithms (e.g. to `none` or HS256 with the public key as secret) to forge a token the server accepts","The header is encrypted","It breaks refresh tokens"],"answer":1,"explanation":"Verification must pin the expected algorithm and key server-side. Historic library bugs accepted `alg: none`, or treated an RSA public key as an HMAC secret. Modern libraries require an explicit algorithm list — use it."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-be-n-plus-one', 'backend', 'intermediate', true, '{"id":"q-pro-be-n-plus-one","topic":"backend","difficulty":"intermediate","pro":true,"prompt":"An endpoint lists 50 posts and their authors. Logs show 51 SQL queries. What''s this and the usual fix?","options":["A memory leak; restart the server","The N+1 query problem; batch the author lookup (JOIN, `WHERE id IN (…)`, or a DataLoader)","Normal behaviour for ORMs","A missing index on posts"],"answer":1,"explanation":"One query for the list, then one per row for the relation. Eager loading (`include`, `select_related`), a join, or batching via DataLoader collapses it to one or two queries."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-fe-hydration', 'frontend', 'advanced', true, '{"id":"q-pro-fe-hydration","topic":"frontend","difficulty":"advanced","pro":true,"prompt":"A server-rendered React page logs \"Text content does not match server-rendered HTML\". The component renders `new Date().toLocaleTimeString()`. Why?","options":["React can''t render dates on the server","The server and client produce different output, so hydration finds a mismatch","The CSS loaded late","useEffect ran twice"],"answer":1,"explanation":"Hydration expects the first client render to match the server HTML exactly. Time, randomness, `window` checks and locale differences break that. Render stable output first, then update in an effect, or mark deliberate differences with `suppressHydrationWarning`."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.questions (id, topic, difficulty, pro, data) values ('q-pro-low-dataverse', 'lowcode', 'intermediate', true, '{"id":"q-pro-low-dataverse","topic":"lowcode","difficulty":"intermediate","pro":true,"prompt":"When does it make sense to move a Power Apps solution from SharePoint lists to Dataverse?","options":["Never — SharePoint is always enough","When you need relational data, row-level security roles, server-side logic and delegation at scale","Only when the app has more than 10 screens","When you want the app to load faster offline"],"answer":1,"explanation":"SharePoint lists are fine for simple, small data. Dataverse gives real relationships, business rules, security roles down to row and column level, auditing and much better delegation support. The trade-off is premium licensing — which is exactly the conversation stakeholders want you to lead."}'::jsonb)
  on conflict (id) do update set topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-closure-loop', 'predict', 'languages', 'beginner', false, '{"id":"c-closure-loop","kind":"predict","title":"The classic closure loop","topic":"languages","difficulty":"beginner","pro":false,"prompt":"What does this print?","code":{"lang":"js","source":"for (var i = 0; i < 3; i++) {\n  setTimeout(() => console.log(i), 0)\n}"},"options":["0 1 2","3 3 3","2 2 2","undefined undefined undefined"],"answer":1,"explanation":"`var` is function-scoped, so all three callbacks close over the *same* `i`. By the time the timers fire, the loop has finished and `i` is 3. Change `var` to `let` and each iteration gets its own binding → `0 1 2`."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-async-foreach', 'bug', 'languages', 'intermediate', false, '{"id":"c-async-foreach","kind":"bug","title":"Await inside forEach","topic":"languages","difficulty":"intermediate","pro":false,"prompt":"This function is supposed to save all users and then log \"done\". Users are often still saving when \"done\" appears. Why?","code":{"lang":"js","source":"async function saveAll(users) {\n  users.forEach(async (u) => {\n    await db.save(u)\n  })\n  console.log(''done'')\n}"},"options":["`db.save` isn''t awaited correctly — it needs `.then()`","`forEach` ignores the promises returned by the async callback, so nothing waits for them","`async` functions can''t be used as callbacks","`console.log` runs on a different thread"],"answer":1,"explanation":"`forEach` calls your callback and throws away its return value — here, a promise. The outer function moves on immediately. Use `await Promise.all(users.map(u => db.save(u)))` for parallel saves, or a `for…of` loop with `await` for sequential ones."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-py-default-arg', 'predict', 'languages', 'intermediate', false, '{"id":"c-py-default-arg","kind":"predict","title":"The mutable default","topic":"languages","difficulty":"intermediate","pro":false,"prompt":"What does the last line print?","code":{"lang":"python","source":"def add_tag(tag, tags=[]):\n    tags.append(tag)\n    return tags\n\nadd_tag(\"react\")\nadd_tag(\"sql\")\nprint(add_tag(\"rag\"))"},"options":["[''rag'']","[''react'', ''sql'', ''rag'']","[''sql'', ''rag'']","TypeError"],"answer":1,"explanation":"Default values are evaluated **once**, when the function is defined. Every call without `tags` shares the same list. The idiom is `tags=None` and then `if tags is None: tags = []` inside the function."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-sql-null', 'predict', 'databases', 'advanced', false, '{"id":"c-sql-null","kind":"predict","title":"NOT IN meets NULL","topic":"databases","difficulty":"advanced","pro":false,"prompt":"`banned_ids` contains the values (2, NULL). How many rows does this return from a `users` table with ids 1, 2, 3?","code":{"lang":"sql","source":"SELECT id FROM users\nWHERE id NOT IN (SELECT user_id FROM banned_ids);"},"options":["2 rows: 1 and 3","1 row: 3","0 rows","An error"],"answer":2,"explanation":"`id NOT IN (2, NULL)` means `id <> 2 AND id <> NULL`. Anything compared to NULL is UNKNOWN, so the whole condition is never TRUE. Zero rows. Use `NOT EXISTS` instead, which handles NULLs the way you expect."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-react-state-batch', 'predict', 'frontend', 'intermediate', false, '{"id":"c-react-state-batch","kind":"predict","title":"Three increments","topic":"frontend","difficulty":"intermediate","pro":false,"prompt":"`count` starts at 0. The button is clicked once. What does it show afterwards?","code":{"lang":"jsx","source":"function Counter() {\n  const [count, setCount] = useState(0)\n  const onClick = () => {\n    setCount(count + 1)\n    setCount(count + 1)\n    setCount(count + 1)\n  }\n  return <button onClick={onClick}>{count}</button>\n}"},"options":["1","3","0","It re-renders three times and shows 3"],"answer":0,"explanation":"`count` is a constant within this render — it''s 0 in all three calls. Each call schedules \"set to 1\", and React batches them into one render. Use the updater form `setCount(c => c + 1)` three times to get 3."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-explain-debounce', 'explain', 'frontend', 'intermediate', false, '{"id":"c-explain-debounce","kind":"explain","title":"What does this utility do?","topic":"frontend","difficulty":"intermediate","pro":false,"prompt":"Explain what calling the returned function does.","code":{"lang":"js","source":"function mystery(fn, ms) {\n  let t\n  return (...args) => {\n    clearTimeout(t)\n    t = setTimeout(() => fn(...args), ms)\n  }\n}"},"options":["Calls `fn` at most once every `ms` milliseconds, starting immediately","Delays `fn` until calls have stopped for `ms` milliseconds, then calls it once with the last arguments","Calls `fn` exactly `ms` times","Retries `fn` after `ms` if it throws"],"answer":1,"explanation":"That''s a **debounce**. Each call cancels the pending timer and starts a new one, so `fn` only runs after a quiet period. Typical use: search-as-you-type. The first option describes **throttle**, which guarantees regular execution during continuous activity (like scroll handlers)."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-complexity-nested', 'complexity', 'fundamentals', 'beginner', false, '{"id":"c-complexity-nested","kind":"complexity","title":"Pairs that sum to target","topic":"fundamentals","difficulty":"beginner","pro":false,"prompt":"What''s the time complexity?","code":{"lang":"python","source":"def has_pair(nums, target):\n    for i in range(len(nums)):\n        for j in range(i + 1, len(nums)):\n            if nums[i] + nums[j] == target:\n                return True\n    return False"},"options":["O(n)","O(n log n)","O(n²)","O(2ⁿ)"],"answer":2,"explanation":"Every pair is checked once: n(n−1)/2 comparisons, which is O(n²). A set-based version is O(n): for each number, check whether `target - x` has been seen, then add `x` to the set."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-impl-race', 'implementation', 'frontend', 'advanced', false, '{"id":"c-impl-race","kind":"implementation","title":"Fetch without the race","topic":"frontend","difficulty":"advanced","pro":false,"prompt":"A search box fetches results whenever `query` changes. Which effect avoids showing results for an old query when responses arrive out of order?","code":{"lang":"jsx","source":"// A\nuseEffect(() => { search(query).then(setResults) }, [query])\n\n// B\nuseEffect(() => {\n  let stale = false\n  search(query).then(r => { if (!stale) setResults(r) })\n  return () => { stale = true }\n}, [query])\n\n// C\nuseEffect(() => { search(query).then(setResults) }, [])"},"options":["A","B","C","All three are equivalent"],"answer":1,"explanation":"When `query` changes, React runs B''s cleanup for the previous effect, marking that response as stale. A slow, older response then gets ignored. A applies whichever response arrives last. C only searches once. An `AbortController` is an even better version of B — it also cancels the network request."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-sql-index-order', 'approach', 'databases', 'intermediate', false, '{"id":"c-sql-index-order","kind":"approach","title":"Which index?","topic":"databases","difficulty":"intermediate","pro":false,"prompt":"This query runs thousands of times a minute. Which single index helps most?","code":{"lang":"sql","source":"SELECT * FROM orders\nWHERE customer_id = $1\nORDER BY created_at DESC\nLIMIT 20;"},"options":["`CREATE INDEX ON orders (created_at)`","`CREATE INDEX ON orders (customer_id, created_at DESC)`","`CREATE INDEX ON orders (created_at, customer_id)`","Separate indexes on each column — Postgres combines them perfectly"],"answer":1,"explanation":"A composite index with the equality column first, then the sort column, lets Postgres jump to one customer''s entries already in date order and stop after 20 rows — no sort step. Column order matters: `(created_at, customer_id)` can''t seek by customer."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-docker-bug', 'bug', 'devops', 'beginner', false, '{"id":"c-docker-bug","kind":"bug","title":"Works on my machine","topic":"devops","difficulty":"beginner","pro":false,"prompt":"This container starts, but the app is unreachable at `localhost:3000` on the host. The app listens on port 3000. What''s missing?","code":{"lang":"dockerfile","source":"FROM node:22-alpine\nWORKDIR /app\nCOPY . .\nRUN npm ci\nCMD [\"node\", \"server.js\"]\n\n# started with:\n# docker run my-app"},"options":["The Dockerfile needs `EXPOSE 3000` or nothing will work","The port isn''t published — run with `-p 3000:3000` (and make sure the app listens on 0.0.0.0, not 127.0.0.1)","Alpine images can''t run Node servers","`CMD` should be `RUN`"],"answer":1,"explanation":"`EXPOSE` is documentation; it doesn''t open anything. `-p host:container` publishes the port. The other classic trap: an app bound to `127.0.0.1` inside the container only accepts connections from inside that container."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-explain-git-rebase', 'explain', 'fundamentals', 'intermediate', false, '{"id":"c-explain-git-rebase","kind":"explain","title":"Read this Git history","topic":"fundamentals","difficulty":"intermediate","pro":false,"prompt":"What did this command do to `feature`?","code":{"lang":"bash","source":"git checkout feature\ngit rebase main"},"options":["Merged main into feature with a merge commit","Replayed feature''s commits on top of main''s latest commit, creating new commits with new hashes","Deleted feature''s commits and copied main","Pushed feature to main"],"answer":1,"explanation":"Rebase takes the commits unique to `feature`, and re-applies them one by one on top of `main`. The result is a linear history, but every replayed commit is new (new parent → new hash). That''s why you shouldn''t rebase commits others have already pulled."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-ts-narrow', 'bug', 'languages', 'intermediate', false, '{"id":"c-ts-narrow","kind":"bug","title":"The narrowing that isn''t","topic":"languages","difficulty":"intermediate","pro":false,"prompt":"TypeScript reports an error on the marked line. Why?","code":{"lang":"ts","source":"type Shape = { kind: ''circle''; r: number } | { kind: ''square''; side: number }\n\nfunction area(s: Shape) {\n  if (s.kind === ''circle'') return Math.PI * s.r ** 2\n  return s.r * s.r // ← error\n}"},"options":["`**` isn''t supported in TypeScript","After the `if`, `s` is narrowed to the square variant, which has no `r`","Discriminated unions need a `switch` statement","`kind` must be a number"],"answer":1,"explanation":"TypeScript narrows on the discriminant: once the circle case returns, the remaining type is `{ kind: ''square''; side: number }`. The fix is `s.side * s.side`. This is exactly the bug discriminated unions exist to catch."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-node-promise-reject', 'predict', 'backend', 'intermediate', false, '{"id":"c-node-promise-reject","kind":"predict","title":"The unhandled rejection","topic":"backend","difficulty":"intermediate","pro":false,"prompt":"In Node.js 22, what happens when this runs?","code":{"lang":"js","source":"async function load() {\n  throw new Error(''db down'')\n}\nload()\nconsole.log(''still running'')\nsetTimeout(() => console.log(''later''), 100)"},"options":["Prints \"still running\" and \"later\"; the error is silently ignored","Prints \"still running\", then the process crashes with the unhandled rejection before \"later\"","Crashes immediately before printing anything","Prints \"db down\" as a warning, then \"later\""],"answer":1,"explanation":"`load()` returns a rejected promise synchronously and nobody handles it. The synchronous log runs first. Once microtasks drain, Node detects the unhandled rejection and — since Node 15 — the default mode is `throw`, which terminates the process. Always `await` or `.catch()` promises."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-rag-approach', 'approach', 'genai', 'intermediate', false, '{"id":"c-rag-approach","kind":"approach","title":"Searching your docs","topic":"genai","difficulty":"intermediate","pro":false,"prompt":"Users search internal docs with queries like \"ERR_4012 refund failed\" and \"how do refunds work?\". Which retrieval approach handles both well?","options":["Pure vector search","Pure keyword (BM25) search","Hybrid search: BM25 + vector similarity, merged (e.g. reciprocal rank fusion)","Ask the LLM to guess which doc is relevant"],"answer":2,"explanation":"Embeddings are great at meaning (\"how do refunds work\") but weak on exact tokens like error codes. BM25 nails exact terms but misses paraphrases. Hybrid retrieval combines both rankings, and is the default recommendation for most production RAG systems."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-powerfx-delegation', 'approach', 'lowcode', 'intermediate', false, '{"id":"c-powerfx-delegation","kind":"approach","title":"Delegable or not?","topic":"lowcode","difficulty":"intermediate","pro":false,"prompt":"A Dataverse table has 120,000 rows. Which formula returns *all* matching records instead of only the first batch?","code":{"lang":"powerfx","source":"// A\nFilter(Tickets, StartsWith(Title, txtSearch.Text))\n// B\nFilter(Tickets, Len(Title) > 10)\n// C\nFilter(Tickets, Right(Title, 3) = \"BUG\")"},"options":["A","B","C","None of them — Dataverse never delegates"],"answer":0,"explanation":"`StartsWith` is delegable to Dataverse, so the server does the filtering. `Len` and `Right` inside a filter can''t be translated to a server query, so Power Apps fetches only the first 500–2,000 rows and filters locally. Prefix search is the delegation-friendly pattern."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-pro-deadlock', 'explain', 'databases', 'advanced', true, '{"id":"c-pro-deadlock","kind":"explain","title":"Two transfers, one deadlock","topic":"databases","difficulty":"advanced","pro":true,"prompt":"Two transactions run at the same time. Why does Postgres abort one of them?","code":{"lang":"sql","source":"-- T1\nUPDATE accounts SET bal = bal - 10 WHERE id = 1;\nUPDATE accounts SET bal = bal + 10 WHERE id = 2;\n-- T2\nUPDATE accounts SET bal = bal - 5 WHERE id = 2;\nUPDATE accounts SET bal = bal + 5 WHERE id = 1;"},"options":["Postgres can''t update two rows in one transaction","Each holds a row lock the other needs — a deadlock; Postgres detects the cycle and aborts one","The balance went negative","Both transactions read stale data"],"answer":1,"explanation":"T1 locks row 1, T2 locks row 2, then each waits on the other. The deadlock detector breaks the cycle by aborting one. The standard fix: always lock rows in a consistent order (e.g. ascending id)."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-pro-memo', 'bug', 'frontend', 'advanced', true, '{"id":"c-pro-memo","kind":"bug","title":"The memo that never memoises","topic":"frontend","difficulty":"advanced","pro":true,"prompt":"`Chart` is wrapped in `React.memo`, yet it re-renders every time `Dashboard` does. Why?","code":{"lang":"jsx","source":"function Dashboard({ data }) {\n  return <Chart data={data} options={{ stacked: true }} onHover={(p) => log(p)} />\n}"},"options":["`React.memo` only works on class components","`options` and `onHover` are new references every render, so the shallow prop comparison fails","`data` is too large to compare","Memoised components always render at least twice"],"answer":1,"explanation":"`memo` compares props with `Object.is`. Inline objects and arrow functions are recreated each render. Hoist constants, use `useMemo` for objects and `useCallback` for handlers — or let the React Compiler do it."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-pro-complexity-heap', 'complexity', 'fundamentals', 'advanced', true, '{"id":"c-pro-complexity-heap","kind":"complexity","title":"Top K from a stream","topic":"fundamentals","difficulty":"advanced","pro":true,"prompt":"You keep the K largest of N numbers using a min-heap of size K. What''s the time complexity?","code":{"lang":"python","source":"import heapq\ndef top_k(nums, k):\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    return heap"},"options":["O(N log N)","O(N log K)","O(N·K)","O(K log N)"],"answer":1,"explanation":"Each of the N elements does a push/pop on a heap of at most K+1 items, costing O(log K). For K ≪ N that''s much better than sorting everything, and uses only O(K) memory."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
insert into public.challenges (id, kind, topic, difficulty, pro, data) values ('c-pro-cache-stampede', 'approach', 'system-design', 'advanced', true, '{"id":"c-pro-cache-stampede","kind":"approach","title":"The midnight stampede","topic":"system-design","difficulty":"advanced","pro":true,"prompt":"A popular cache key expires and 5,000 requests hit the database simultaneously to rebuild it. Which approach prevents this?","options":["Shorter TTLs","More database replicas only","Request coalescing / a rebuild lock (one request recomputes, others wait or get stale data), plus jittered TTLs","Disable the cache at peak hours"],"answer":2,"explanation":"A thundering herd happens when many readers miss at once. Let one request take a lock and recompute while others serve the stale value (stale-while-revalidate), and add random jitter so keys don''t expire together."}'::jsonb)
  on conflict (id) do update set kind = excluded.kind, topic = excluded.topic, difficulty = excluded.difficulty, pro = excluded.pro, data = excluded.data;
